const equal=(a,b,tolerance)=>a===b||typeof a==='number'&&typeof b==='number'&&Math.abs(a-b)<=tolerance||a&&b&&typeof a==='object'&&typeof b==='object'&&Array.isArray(a)===Array.isArray(b)&&Object.keys(a).length===Object.keys(b).length&&Object.keys(a).every(k=>Object.hasOwn(b,k)&&equal(a[k],b[k],tolerance));
export function reduceRecordedKeys(keys,tolerance=1e-4){
 if(!Number.isFinite(tolerance)||tolerance<0)throw Error('키 오차 범위 오류');if(keys.length<3)return structuredClone(keys);
 if(keys.some(k=>k.interpolation==='step'||typeof k.value!=='number'&&!Array.isArray(k.value))){const out=[];for(let i=0;i<keys.length;i++)if(i===0||i===keys.length-1||!equal(keys[i].value,keys[i-1].value,0))out.push(structuredClone(keys[i]));return out;}
 const keep=new Set([0,keys.length-1]),pending=[[0,keys.length-1]];while(pending.length){const [first,last]=pending.pop();if(last-first<=1)continue;let index=-1,error=tolerance;const a=keys[first],b=keys[last];for(let i=first+1;i<last;i++){const alpha=(keys[i].time-a.time)/(b.time-a.time),expected=Array.isArray(a.value)?a.value.map((v,k)=>v+(b.value[k]-v)*alpha):a.value+(b.value-a.value)*alpha,actual=keys[i].value,distance=Array.isArray(actual)?Math.max(...actual.map((v,k)=>Math.abs(v-expected[k]))):Math.abs(actual-expected);if(distance>error){index=i;error=distance;}}if(index>=0){keep.add(index);pending.push([first,index],[index,last]);}}
 return [...keep].sort((a,b)=>a-b).map(i=>structuredClone(keys[i]));
}
export class TakeRecorder {
  constructor({name='Take',fps=30,targets=[],properties=['position','rotation','scale','visible'],capture,includeComponents=true,includeStructure=false,includeSkeleton=false,includeAudio=false}={}){if(typeof name!=='string'||!name||name.length>80||![includeComponents,includeStructure,includeSkeleton,includeAudio].every(v=>typeof v==='boolean')||!Array.isArray(targets)||new Set(targets).size!==targets.length||targets.some(v=>typeof v!=='string'||!v)||!Number.isInteger(fps)||fps<1||fps>240||!Array.isArray(targets)||!targets.length||!properties.every(p=>['position','rotation','scale','visible'].includes(p)))throw Error('녹화 대상·속성·FPS 오류');Object.assign(this,{name,fps,targets:[...targets],properties,capture,includeComponents,includeStructure,includeSkeleton,includeAudio,audioVoices:new Map(),structure:new Map(),time:0,next:0,tracks:new Map(),componentBindings:new Map(),frames:0,closed:false});}
  sample(time,objects){if(this.closed)throw Error('녹화가 종료됐어요.');if(!Number.isFinite(time)||time<0||time<this.time)throw Error('녹화 시간 오류');this.time=time;if(time+1e-9<this.next)return;this.next=time+1/this.fps;this.frames++;const owners=new Map(objects.map(o=>[o.id,o]));
   for(const target of this.targets){const object=owners.get(target);if(!object)continue;const rows=this.properties.map(property=>({key:property,type:property,value:object[property],discrete:property==='visible'}));if(this.includeComponents&&!this.includeStructure){let cached=this.componentBindings.get(target);if(cached?.object!==object){cached={object,rows:recordableComponents(object)};this.componentBindings.set(target,cached);}const components=new Map((object.components||[]).map(c=>[c.id,c]));for(const row of cached.rows){const c=components.get(row.component);if(c?.type===row.componentType)rows.push({...row,value:c.properties?.[row.property]??row.default,key:row.component+'|'+row.property,type:'component'});}}
    if(this.includeStructure){const previous=this.structure.get(target)||new Set(),current=new Set();for(const c of object.components||[]){if(c.type==='Transform')continue;current.add(c.id);rows.push({key:'state|'+c.id,type:'componentState',component:c.id,name:c.name||c.type,value:c,discrete:true});}for(const id of previous)if(!current.has(id))rows.push({key:'state|'+id,type:'componentState',component:id,value:null,discrete:true});this.structure.set(target,current);}if(this.includeSkeleton){const pose=this.capture?.(object);if(pose?.length||this.tracks.has(target+'|pose'))rows.push({key:'pose',type:'skeletalPose',value:pose||[],discrete:false});}
    for(const row of rows){const key=target+'|'+row.key;let track=this.tracks.get(key);if(!track){track=makeSequenceTrack(row.type);track.keys=[];track.target=target;track.name=(object.name+' · '+(row.type==='skeletalPose'?'골격 포즈':row.type==='componentState'?row.name||'컴포넌트':{position:'위치',rotation:'회전',scale:'크기',visible:'표시'}[row.type]||row.key)).slice(0,80);if(row.type==='componentState'){track.component=row.component;if(time>0)track.keys.push({time:0,value:null,interpolation:'step'});}if(row.type==='component')Object.assign(track,{component:row.component,componentType:row.componentType,property:row.property});this.tracks.set(key,track);}const value=row.value&&typeof row.value==='object'?structuredClone(row.value):row.value;if(value===undefined)continue;const last=track.keys.at(-1),entry={time,value,interpolation:row.discrete?'step':'linear'};const previous=track.keys.at(-2);if(last&&previous&&last.time<time&&equal(previous.value,last.value,0)&&equal(last.value,value,0))last.time=time;else if(!last||last.time<time)track.keys.push(entry);else Object.assign(last,entry);if(track.keys.length>1000000)throw Error('녹화 메모리 예산 초과');}
   }
  }
  audioStart(id,{owner,clip,sourceStart=0,rate=1,loop=false,duration=Infinity}){if(!this.includeAudio||this.closed||!this.targets.includes(owner))return;this.audioStop(id);if(typeof clip!=='string'||!Number.isFinite(sourceStart)||sourceStart<0||!Number.isFinite(rate)||rate<=0)throw Error('녹화 오디오 큐 오류');this.audioVoices.set(id,{owner,clip,sourceStart,rate,loop,duration,start:this.time});}
  audioStop(id){const v=this.audioVoices.get(id);if(!v)return;this.audioVoices.delete(id);const duration=this.time-v.start;if(duration<=0)return;const key=v.owner+'|audio|'+id;let track=this.tracks.get(key);if(!track){track=makeSequenceTrack('audio');track.target=v.owner;track.name='Audio '+String(id).slice(0,60);this.tracks.set(key,track);}let elapsed=0,sourceStart=v.sourceStart;while(elapsed<duration-1e-9){if(v.loop&&Number.isFinite(v.duration)&&v.duration>0)sourceStart%=v.duration;const length=v.loop&&Number.isFinite(v.duration)&&v.duration>0?Math.min(duration-elapsed,(v.duration-sourceStart)/v.rate):duration-elapsed;if(length<=0)break;track.clips.push({id:crypto.randomUUID(),clip:v.clip,start:v.start+elapsed,duration:length,sourceStart,rate:v.rate,slot:'DefaultSlot'});if(track.clips.length>256)throw Error('오디오 녹화 클립 예산을 넘었어요.');elapsed+=length;sourceStart=0;}}
  finish({tolerance=1e-4}={}){for(const id of [...this.audioVoices.keys()])this.audioStop(id);const tracks=[...this.tracks.values()];for(const track of tracks)track.keys=track.type==='skeletalPose'?reduceSkeletalKeys(track.keys,tolerance):reduceRecordedKeys(track.keys,tolerance);const data={version:1,name:this.name,length:Math.max(.001,this.time),rate:1,fps:this.fps,loop:false,restoreState:true,tracks};if(!validGameplayAsset('sequenceasset',data))throw Error('녹화 결과가 시퀀스 키 예산을 넘었어요. 녹화 시간을 줄이거나 키 오차를 늘리세요.');this.closed=true;return data;}
}
